\|(a + b \omega + c \omega^2)^3\| &= |a^3 + b^3 + c^3| + |3a^2 b \omega + 3ab^2 \omega^2 +} 3a^2 c \omega^2 + 3ac^2 \omega + 3b^2 c \omega^2 + 3bc^2 \omega| \\
